// src/lib/og/fonts.ts
//
// Fonts for the share card image (see lib/og/post-card.tsx). Embedded in the code on purpose:
// fetching a font from the web while an image is being drawn is one more thing that can fail,
// and a social network's crawler gives up quickly. Liberation Sans (SIL Open Font License),
// cut down to Latin, the Yoruba/Igbo letters and tone marks, and the Naira sign, as WOFF.

export type OgFont = { name: string; data: ArrayBuffer; weight: 400 | 700; style: 'normal' }

const REGULAR_B64 = ''
const BOLD_B64 = ''

function toBuffer(b64: string): ArrayBuffer {
  const bin = atob(b64)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  return bytes.buffer
}

let cached: OgFont[] | null = null

export function loadOgFonts(): OgFont[] {
  if (!cached) {
    cached = [
      { name: 'Liberation Sans', data: toBuffer(REGULAR_B64), weight: 400, style: 'normal' },
      { name: 'Liberation Sans', data: toBuffer(BOLD_B64), weight: 700, style: 'normal' },
    ]
  }
  return cached
}
